declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requireAdmin();$test=(string)($_GET['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin access required.');}$workflow=(string)($_GET['workflow']??'');
$modes=['manual'=>['Manual Scoring','category.php','Open','dark','✎','Create and score categories entirely in the Manual workflow.'],'automatic'=>['Automatic Scoring','automatic-setup.php','Open','primary','⚙','Manage each event and all its secure judge-link categories in one place.'],'projection'=>['Live Projection','projection-control.php','Open','danger','▣','Control the audience screen for any Dance Cup category.']];
if(!isset($modes[$workflow])){header('Location: ./'.($test?'?data_mode=test':''),true,303);exit;}
$pdo=Database::connection();DanceCupScoringService::ensureWorkspaceTables($pdo,$test);$tables=DanceCupScoringService::tables($test);$prefix=$test?'bdc_test_dance_cup':'bdc_dance_cup';$sql="SELECT c.id,c.event_id,c.category_name,c.dance_style,c.competition_level,c.entry_type,c.round_name,c.status,c.scoring_mode,e.name event_name,e.event_date,e.end_date,e.venue,e.country,(SELECT COUNT(*) FROM {$prefix}_entries x WHERE x.competition_id=c.id AND x.status='active') participant_count,(SELECT COUNT(*) FROM {$prefix}_judges x WHERE x.competition_id=c.id) judge_count,(SELECT COUNT(*) FROM {$prefix}_marks x WHERE x.competition_id=c.id) mark_count FROM {$tables['competitions']} c JOIN {$tables['events']} e ON e.id=c.event_id WHERE e.status<>'archived'";$params=[];if($workflow!=='projection'){$sql.=" AND c.scoring_mode=:mode";$params['mode']=$workflow;}$sql.=" ORDER BY e.event_date DESC,e.id DESC,c.category_name,c.id";$query=$pdo->prepare($sql);$query->execute($params);$categories=$query->fetchAll();$events=[];foreach($categories as $category){$eventId=(int)$category['event_id'];if(!isset($events[$eventId]))$events[$eventId]=['id'=>$eventId,'name'=>$category['event_name'],'event_date'=>$category['event_date'],'end_date'=>$category['end_date'],'venue'=>$category['venue'],'country'=>$category['country'],'categories'=>[]];$events[$eventId]['categories'][]=$category;}
[$label,$route,$actionLabel,$colour,$icon,$description]=$modes[$workflow];$suffix=$test?'&data_mode=test':'';$creationWorkflow=$workflow==='projection'?'manual':$workflow;$creationHref='index.php?workflow='.rawurlencode($creationWorkflow).$suffix;
ob_start(static function(string $html)use($creationHref):string{
    $css='.workflow-start{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;padding:18px;border:2px solid #f2b817;border-radius:20px;background:linear-gradient(120deg,#fff9df,#fff);box-shadow:0 12px 30px rgba(143,101,0,.12)}.start-choice{display:flex;align-items:center;gap:16px;min-height:108px;padding:20px;border:1px solid #e4c45e;border-radius:15px;background:#fff;color:#172033;text-decoration:none;transition:.15s ease}.start-choice:hover{border-color:#e4a900;box-shadow:0 8px 20px rgba(143,101,0,.14);transform:translateY(-1px);color:#172033}.start-choice.primary{background:#f7bd22;border-color:#d99d00}.start-number{display:grid;place-items:center;flex:0 0 48px;height:48px;border-radius:50%;background:#172f57;color:#fff;font-size:1.2rem;font-weight:900}.start-choice strong{display:block;font-size:1.08rem}.start-choice small{display:block;margin-top:3px;color:#667085}.start-choice.primary small{color:#55400a}@media(max-width:700px){.workflow-start{grid-template-columns:1fr;padding:12px}.start-choice{min-height:92px;padding:16px}}';
    $html=str_replace('</style>',$css.'</style>',$html);
    $start='<section class="workflow-start mb-4" aria-labelledby="start-workflow-title"><div><div class="event-kicker">START OR EXPAND</div><h2 class="h4 mb-1" id="start-workflow-title">What do you want to set up?</h2><p class="text-muted mb-0">Begin at Step 1, or add another category to an event you already created.</p></div><div></div><a class="start-choice primary" href="'.e($creationHref).'#create-event"><span class="start-number">1</span><span><strong>Create a new event</strong><small>Add the event name, date and venue first.</small></span></a><a class="start-choice" href="'.e($creationHref).'#create-category"><span class="start-number">2</span><span><strong>Add category to existing event</strong><small>Choose an event, category type and scoring criteria.</small></span></a></section>';
    $heading='<div class="d-flex justify-content-between align-items-center gap-3 flex-wrap mb-3"><div><div class="event-kicker">YOUR EVENTS</div>';
    $html=str_replace($heading,$start.$heading,$html);
    $toolbar='#<div class="top-actions"><a class="btn btn-outline-secondary" href="([^\"]*)">Back</a><a class="btn btn-warning" href="[^\"]*">(?:Manage Events &amp; Categories|Add Event or Category)</a></div>#';
    return preg_replace($toolbar,'<div class="top-actions"><a class="btn btn-outline-secondary" href="$1">Back</a></div>',$html,1)??$html;
});
