p:.4rem;flex-wrap:wrap}.meta span{padding:.3rem .55rem;border-radius:999px;background:#eef2f7;font-size:.74rem;font-weight:700}.next-step{padding:12px;border-radius:12px;background:#f4f7fb;border-left:4px solid #2563eb}.next-step small{display:block;color:#667085}.category-actions{margin-top:auto}.secondary-actions{display:flex;gap:14px;justify-content:center;margin-top:10px;font-size:.82rem}.secondary-actions a{text-decoration:none}.advanced-tools{padding:0 18px 18px}.advanced-tools>div{padding:12px 14px;border:1px dashed #b8c4d3;border-radius:12px;background:#fbfcfe;color:#667085}.top-actions{display:flex;gap:8px;flex-wrap:wrap}.empty-state{border:1px dashed #b8c4d3;border-radius:20px;background:#fff}@media(max-width:1050px){.journey{grid-template-columns:repeat(3,1fr)}.category-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.workflow-hero{border-radius:18px}.journey{grid-template-columns:1fr 1fr}.journey-step{font-size:.72rem}.event-head{align-items:flex-start;padding:18px}.event-title{font-size:1.12rem}.event-count{min-width:76px}.category-grid{grid-template-columns:1fr;padding:12px}.category-card h3{min-height:0}.top-actions{width:100%}.top-actions .btn{flex:1 1 auto}}
</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./<?=$test?'?data_mode=test':''?>">Dance Cup</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container workflow-shell py-4"><section class="workflow-hero p-4 p-lg-5 mb-3"><div class="d-flex align-items-center gap-3"><div class="workflow-icon"><?=e($icon)?></div><div><div class="text-uppercase small fw-bold text-warning"><?=$test?'TEST · ':''?>DANCE CUP EVENT WORKSPACE</div><h1 class="h2 mb-1">Run your Dance Cup step by step</h1><p class="mb-0 opacity-75">Choose an event below and continue from the next unfinished step. You do not need to understand the system modules.</p></div></div></section><nav class="journey mb-4" aria-label="Dance Cup workflow"><?php foreach(['Event details','Categories','Participants','Judges','Scoring','Results & publish'] as $number=>$step):?><div class="journey-step"><b><?=$number+1?></b><span><?=e($step)?></span></div><?php endforeach;?></nav><?php if(isset($_GET['deleted'])):?><div class="alert alert-success">Draft category deleted safely.</div><?php endif;?>
<div class="d-flex justify-content-between align-items-center gap-3 flex-wrap mb-3"><div><div class="event-kicker">YOUR EVENTS</div><h2 class="h4 mb-0">Choose where to continue</h2></div><div class="top-actions"><a class="btn btn-outline-secondary" href="./<?=$test?'?data_mode=test':''?>">Back</a><a class="btn btn-warning" href="index.php?workflow=<?=e($creationWorkflow)?><?=$suffix?>"><?=$workflow==='projection'?'Manage Events & Categories':'Add Event or Category'?></a></div></div>
