<?php foreach($event['categories'] as $category):?><?php $participants=(int)$category['participant_count'];$judges=(int)$category['judge_count'];$marks=(int)$category['mark_count'];$status=(string)$category['status'];if($workflow==='projection'){$nextTitle='Step 5 · Audience screen';$nextText='Open projection controls for this category.';}elseif($participants<1){$nextTitle='Step 3 · Add participants';$nextText='Add the competitors or teams for this category.';}elseif($workflow==='automatic'&&$judges<1){$nextTitle='Step 4 · Assign judges';$nextText='Choose judges and create their secure scoring links.';}elseif($marks<1){$nextTitle='Step 5 · Start scoring';$nextText=$workflow==='automatic'?'Judge links are ready. Open the workspace and begin scoring.':'Open the score sheet and enter the judges’ marks.';}elseif($status==='pending_approval'){$nextTitle='Step 6 · Waiting for approval';$nextText='Scores are locked and ready for Super Admin review.';}elseif($status==='approved'){$nextTitle='Complete';$nextText='Results are approved and published.';}else{$nextTitle='Step 5 · Continue scoring';$nextText='Saved work is ready. Continue from where you stopped.';}?><article class="card category-card h-100"><div class="card-body d-flex flex-column"><h3 class="h5"><?=e($category['category_name'])?></h3><div class="meta mb-3"><span><?=e(ucwords(str_replace('_',' ',$category['dance_style'])))?></span><span><?=e(ucwords(str_replace('_',' ',$category['competition_level'])))?></span><span><?=e(ucwords(str_replace('_',' ',$category['entry_type'])))?></span><span><?=$participants?> participant<?=$participants===1?'':'s'?></span><span><?=$judges?> judge<?=$judges===1?'':'s'?></span></div><div class="next-step mb-3"><strong><?=e($nextTitle)?></strong><small><?=e($nextText)?></small></div><div class="category-actions"><a class="btn btn-<?=e($colour)?> w-100" href="<?=e($route)?>?id=<?=(int)$category['id']?><?=$suffix?>"><?=$status==='approved'?'View completed category':'Continue'?></a><?php if($workflow!=='projection'):?><div class="secondary-actions"><a href="category-edit.php?id=<?=(int)$category['id']?><?=$suffix?>">Edit category</a><?php if($category['status']==='draft'):?><a class="text-danger" href="delete-draft.php?id=<?=(int)$category['id']?><?=$suffix?>">Delete draft</a><?php endif;?></div><?php endif;?></div></div></article><?php endforeach;?></div><?php if($workflow==='automatic'):?><div class="advanced-tools"><div><strong>Using the same judges for several categories?</strong> <a href="panels.php?event_id=<?=(int)$event['id']?><?=$suffix?>">Set up a shared judging panel</a>. This is optional.</div></div><?php endif;?></section><?php endforeach;?>
